const animalProto = {
  init(name, sound) {
    this.name = name
    this.sound = sound
    return this // chaining ke liye
  },
  speak() {
    return `${this.name} makes ${this.sound}`
  }
}

const cat = Object.create(animalProto)
cat.init("Whiskers", "Meow")
